<script setup lang="ts">
import {computed,onScopeDispose,reactive,ref,shallowRef,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRouter} from 'vue-router'
import {Plus,Monitor,Cellphone,Grid} from '@element-plus/icons-vue'
import {can,currentProject,projectId,session} from '@/core/session'
import {ApiError,IdentityChanged,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {typeDeviceUuid} from '../device-types/type-devices-api'
import PageHeader from '@/ui/PageHeader.vue'
import AsyncState from '@/ui/AsyncState.vue'
import CursorPager from '@/ui/CursorPager.vue'
import {isUserApplicationKind,prepareUserApplication,userApplicationMatches,userApplicationTransport,type UserApplication,type UserApplicationKind,type UserApplicationKindEntry,type UserApplicationTransport,type UserApplicationIntent,type UserApplicationDraft} from './user-application-api'
const props=withDefaults(defineProps<{mode?:'directory'|'select'|'create';kind?:string;transport?:UserApplicationTransport}>(),{mode:'directory',transport:()=>userApplicationTransport})
const router=useRouter(),roles=['OWNER','ADMIN','OPERATOR','VIEWER'],denied=ref(false)
const member=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&typeDeviceUuid.test(projectId.value)&&can('application:read')&&roles.includes(session.user?.projectRole||'')&&roles.includes(currentProject.value?.myRole||'')&&['ACTIVE','ARCHIVED'].includes(currentProject.value?.status||'')),readable=computed(()=>member.value&&!denied.value)
const writable=computed(()=>readable.value&&can('application:manage')&&currentProject.value?.status==='ACTIVE'&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||''))
const rows=shallowRef<readonly UserApplication[]>([]),kinds=shallowRef<readonly UserApplicationKindEntry[]>([]),loading=ref(false),loadFailed=ref(false),error=ref(''),busy=ref(false),unknown=ref(false),intent=shallowRef<UserApplicationIntent>(),created=shallowRef<UserApplication>(),detail=shallowRef<UserApplication>(),detailTarget=shallowRef<UserApplication>(),detailShown=ref(false),detailBusy=ref(false),detailError=ref(''),page=ref(1),cursors=ref<(string|undefined)[]>([undefined]),nextCursor=ref<string|null>(null)
const draft=reactive<UserApplicationDraft>({kind:'USER_MOBILE',name:'',description:'',tags:[{name:'',value:''}]}),selectedKind=computed(()=>kinds.value.find(row=>row.kind===props.kind)),blocked=computed(()=>busy.value||unknown.value)
const labels:Record<UserApplicationKind,string>={USER_MOBILE:'ThingsX',USER_WEB:'ThingsXS',USER_TABLET:'ThingsPad'},descriptions:Record<UserApplicationKind,string>={USER_MOBILE:'面向用户的手机 App，设备面板可自定义，面向 iOS、Android、小程序和手机网页版。',USER_WEB:'面向用户的 SaaS，专为 PC 浏览器设计，可配置个性化样式。',USER_TABLET:'面向用户的平板 App，用于展示看板和设备控制面板。'},icons={USER_MOBILE:Cellphone,USER_WEB:Monitor,USER_TABLET:Grid}
let generation=0,alive=true,controller:AbortController|undefined
function capture(){return{generation,epoch:identityEpoch(),project:projectId.value,actor:session.user?.accountId,mode:props.mode,kind:props.kind}}
function current(value:ReturnType<typeof capture>){return alive&&readable.value&&value.generation===generation&&value.epoch===identityEpoch()&&value.project===projectId.value&&value.actor===session.user?.accountId&&value.mode===props.mode&&value.kind===props.kind}
function reset(){generation++;controller?.abort();rows.value=[];kinds.value=[];loading.value=false;loadFailed.value=false;busy.value=false;unknown.value=false;intent.value=undefined;created.value=undefined;detail.value=undefined;detailTarget.value=undefined;detailShown.value=false;detailBusy.value=false;detailError.value='';error.value='';page.value=1;cursors.value=[undefined];nextCursor.value=null;Object.assign(draft,{kind:isUserApplicationKind(props.kind)?props.kind:'USER_MOBILE',name:'',description:'',tags:[{name:'',value:''}]})}
function fail(cause:unknown){if(cause instanceof ApiError&&[401,403].includes(cause.status)){reset();denied.value=true}error.value=errorMessage(cause)}
async function load(){if(!readable.value||loading.value||blocked.value)return;const state=capture();loading.value=true;loadFailed.value=false;error.value='';controller=new AbortController();try{if(props.mode==='directory'){const value=await props.transport.list(state.project,cursors.value[page.value-1],controller.signal);if(current(state)){rows.value=value.items;nextCursor.value=value.hasMore?value.nextCursor:null}}else{const value=await props.transport.kinds(state.project,controller.signal);if(current(state))kinds.value=value}}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged)){loadFailed.value=true;fail(cause)}}finally{if(current(state))loading.value=false}}
function scopeChanged(){reset();denied.value=false;if(member.value)void load()}
async function changePage(target:number){if(loading.value||blocked.value||target<1||Math.abs(target-page.value)!==1)return;if(target>page.value){if(!nextCursor.value)return;cursors.value[target-1]=nextCursor.value}page.value=target;rows.value=[];await load()}
function select(kind:UserApplicationKind){if(!writable.value||blocked.value||!kinds.value.some(row=>row.kind===kind))return;void router.push({name:'user-application-create',params:{kind}})}
function cancel(){if(!blocked.value)void router.push({name:'user-applications'})}
function addTag(){if(writable.value&&!blocked.value&&draft.tags.length<20)draft.tags.push({name:'',value:''})}
async function verify(value:UserApplication,original:UserApplicationIntent,state:ReturnType<typeof capture>){if(!userApplicationMatches(value,original))throw new Error('创建回执与原应用资料不符，请按原键核对');const actual=await props.transport.read(state.project,value.id,controller!.signal);if(!current(state))return;if(actual.id!==value.id||!userApplicationMatches(actual,original))throw new Error('当前应用资料与原创建回执不同，请按原键核对');created.value=actual;unknown.value=false;intent.value=undefined;error.value=''}
async function submit(){if(!writable.value||props.mode!=='create'||!selectedKind.value||blocked.value||created.value)return;let original:UserApplicationIntent;try{original=prepareUserApplication(projectId.value,draft)}catch(cause){error.value=errorMessage(cause);return}intent.value=original;unknown.value=true;busy.value=true;error.value='';const state=capture();controller=new AbortController();let accepted=false;try{const value=await props.transport.create(original,controller.signal);accepted=true;if(current(state))await verify(value,original,state)}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged)){const rejected=!accepted&&cause instanceof ApiError&&!cause.outcomeUnknown&&cause.code!==10014&&[400,401,403,404,409,413,422,429].includes(cause.status);if(rejected){unknown.value=false;intent.value=undefined}fail(cause)}}finally{if(current(state))busy.value=false}}
async function recover(){const original=intent.value;if(!original||!unknown.value||busy.value||!readable.value)return;const state=capture();busy.value=true;error.value='';controller=new AbortController();try{const value=await props.transport.recover(original,controller.signal);if(current(state))await verify(value,original,state)}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&cause.status===404)error.value='尚未找到本次创建原件，结果仍未知；请继续按原键读取。';else fail(cause)}}finally{if(current(state))busy.value=false}}
async function view(value:UserApplication){if(!readable.value||blocked.value||detailBusy.value||!rows.value.includes(value))return;const state=capture();detail.value=undefined;detailTarget.value=value;detailShown.value=true;detailBusy.value=true;detailError.value='';controller=new AbortController();try{const actual=await props.transport.read(state.project,value.id,controller.signal);if(current(state)){if(actual.id!==value.id)throw new Error('返回的用户应用身份不符，请重新读取');detail.value=actual}}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&[401,403].includes(cause.status))fail(cause);else detailError.value=errorMessage(cause)}}finally{if(current(state))detailBusy.value=false}}
watch([()=>projectId.value,()=>session.user?.accountId,member,()=>props.mode,()=>props.kind],scopeChanged,{immediate:true,flush:'sync'})
const dispose=onIdentityChange(scopeChanged);onScopeDispose(()=>{alive=false;reset();dispose();window.removeEventListener('beforeunload',beforeUnload)})
onBeforeRouteLeave(()=>!blocked.value);onBeforeRouteUpdate(()=>!blocked.value)
function beforeUnload(event:BeforeUnloadEvent){if(blocked.value){event.preventDefault();event.returnValue=''}}window.addEventListener('beforeunload',beforeUnload)
</script>
<template><div class="tl-page user-applications"><PageHeader :title="mode==='directory'?'用户应用':mode==='select'?'选择用户应用':'创建用户应用'" :back="mode!=='directory'" :back-disabled="blocked" @back="cancel"><el-button v-if="mode==='directory'&&writable" type="primary" :icon="Plus" @click="router.push({name:'user-application-select'})">创建应用</el-button></PageHeader>
 <p v-if="mode!=='create'" class="scope-note">当前可管理用户应用草稿资料；应用运行和客户端发布尚未接入。</p>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <template v-if="unknown"><el-alert title="本次创建结果待核对；保留原请求，只读取原件，不会再次创建。" type="warning" :closable="false"/><p>{{labels[draft.kind]}} · {{intent?.body.name}}</p><el-button :loading="busy" :disabled="!readable" @click="recover">按原键读取创建结果</el-button></template>
 <template v-else-if="created"><el-alert title="用户应用草稿元数据已创建" type="success" :closable="false"/><dl><dt>名称</dt><dd>{{created.name}}</dd><dt>类型</dt><dd>{{labels[created.kind]}}</dd><dt>描述</dt><dd>{{created.description||'—'}}</dd><dt>标签</dt><dd>{{created.tags.map(row=>row.name+'：'+row.value).join('、')||'—'}}</dd></dl><p class="scope-note">当前已创建草稿元数据，尚未形成应用运行配置或客户端发布物。</p><el-button type="primary" @click="cancel">返回用户应用</el-button></template>
 <AsyncState v-else :forbidden="!readable" :loading="loading" :error="loadFailed?error:undefined" @retry="load"><template v-if="mode==='directory'"><div v-if="!rows.length" class="application-empty"><el-empty description="创建面向用户的应用"/><p>您可以创建面向用户的移动应用、桌面应用或平板应用。</p><el-button v-if="writable" type="primary" @click="router.push({name:'user-application-select'})">创建应用</el-button></div><template v-else><div class="application-directory"><article v-for="row in rows" :key="row.id"><el-icon><component :is="icons[row.kind]"/></el-icon><div><h3>{{row.name}}</h3><p>{{labels[row.kind]}} · 草稿</p><p>{{row.description||'—'}}</p><div class="application-tags"><el-tag v-for="tag in row.tags" :key="tag.name" size="small">{{tag.name}}：{{tag.value}}</el-tag></div></div><el-button @click="view(row)">查看资料</el-button></article></div><CursorPager :page="page" :has-next="!!nextCursor" :loading="loading" :show-sizes="false" @update:page="changePage"/></template><el-button v-if="error" @click="load">重新读取目录</el-button></template>
 <template v-else-if="!writable"><p class="scope-note">当前账号或项目没有创建用户应用的权限。</p></template>
 <div v-else-if="mode==='select'" class="application-types"><article v-for="entry in kinds" :key="entry.kind"><el-icon><component :is="icons[entry.kind]"/></el-icon><h2>{{labels[entry.kind]}}</h2><p>{{descriptions[entry.kind]}}</p><el-button type="primary" @click="select(entry.kind)">创建应用</el-button></article></div>
 <el-form v-else-if="selectedKind" class="application-create" label-position="top" :disabled="blocked" @submit.prevent="submit"><p class="selected-kind">{{labels[draft.kind]}}</p><el-form-item label="名称"><el-input v-model="draft.name" aria-label="用户应用名称" maxlength="128"/></el-form-item><el-form-item label="描述"><el-input v-model="draft.description" aria-label="用户应用描述" type="textarea" :rows="3" maxlength="512"/></el-form-item><el-form-item label="标签"><div class="tag-rows"><div v-for="(tag,index) in draft.tags" :key="index" class="tag-row"><el-input v-model="tag.name" :aria-label="`标签名称 ${index+1}`" placeholder="标签名称，比如：版本" maxlength="64"/><el-input v-model="tag.value" :aria-label="`标签值 ${index+1}`" placeholder="标签值，比如：1.0.2" maxlength="256"/><el-button @click="draft.tags.splice(index,1)">移除</el-button></div><el-button :disabled="draft.tags.length>=20" @click="addTag">添加标签</el-button></div></el-form-item><div class="create-actions"><el-button type="primary" :loading="busy" @click="submit">创建</el-button><el-button @click="cancel">取消</el-button></div><p class="scope-note">创建后可在目录中查看应用资料。</p></el-form><p v-else class="scope-note">未找到支持的应用类型，请返回重新选择。</p>
 </AsyncState>
 <el-dialog :model-value="detailShown&&readable" title="用户应用资料" width="min(640px,94vw)" :show-close="!detailBusy" :close-on-click-modal="!detailBusy" :close-on-press-escape="!detailBusy" @close="detailShown=false"><AsyncState :loading="detailBusy" :error="detailError" @retry="detailTarget&&view(detailTarget)"><dl v-if="detail"><dt>名称</dt><dd>{{detail.name}}</dd><dt>类型</dt><dd>{{labels[detail.kind]}}</dd><dt>描述</dt><dd>{{detail.description||'—'}}</dd><dt>标签</dt><dd>{{detail.tags.map(row=>row.name+'：'+row.value).join('、')||'—'}}</dd><dt>状态</dt><dd>草稿</dd></dl></AsyncState><template #footer><el-button :disabled="detailBusy" @click="detailShown=false">关闭</el-button></template></el-dialog>
</div></template>
<style scoped>.user-applications>.el-alert{margin-bottom:20px}.scope-note{color:var(--tl-muted);font-size:13px;line-height:22px;margin:20px 0}.application-empty{text-align:center;padding:50px 20px}.application-empty>p{color:var(--tl-muted);margin-bottom:24px}.application-types{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.application-types article{border:1px solid var(--tl-border);padding:30px 24px;border-radius:4px;display:flex;align-items:flex-start;flex-direction:column}.application-types .el-icon{font-size:42px;color:var(--tl-primary);margin-bottom:12px}.application-types h2{font-size:20px;font-weight:400;margin:0 0 12px}.application-types p{color:var(--tl-muted);font-size:14px;line-height:24px;flex:1;margin:0 0 24px}.application-create{max-width:760px}.selected-kind{color:var(--tl-muted);margin:0 0 22px}.tag-rows{width:100%}.tag-row{display:flex;gap:12px;margin-bottom:12px}.create-actions{display:flex;gap:12px;margin-top:28px}.create-actions .el-button+.el-button{margin-left:0}.application-directory{display:grid;gap:16px}.application-directory article{border:1px solid var(--tl-border);padding:24px;display:flex;gap:20px;align-items:center;border-radius:4px}.application-directory article>.el-icon{font-size:36px;color:var(--tl-primary)}.application-directory article>div{flex:1;min-width:0}.application-directory h3{margin:0 0 10px;font-size:18px;font-weight:400}.application-directory p{margin:8px 0;font-size:13px;color:var(--tl-muted);overflow-wrap:anywhere}.application-tags{display:flex;gap:6px;flex-wrap:wrap}dl{display:grid;grid-template-columns:80px minmax(0,1fr);gap:16px;font-size:14px}dt{color:var(--tl-muted)}dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap}@media(max-width:900px){.application-types{grid-template-columns:minmax(0,1fr)}}@media(max-width:560px){.tag-row{flex-wrap:wrap}.tag-row .el-input{flex-basis:100%}.application-directory article{flex-wrap:wrap}}
</style>
